import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent(`<!doctype html><html lang="ar" dir="rtl"><body style="font:11px -apple-system,sans-serif">
<span id="a" style="letter-spacing:0.12em">يوم نادٍ</span>
<span id="b" style="letter-spacing:normal">يوم نادٍ</span>
<span id="c" style="letter-spacing:0.1em">إجمالي الرفع</span>
<span id="d" style="letter-spacing:normal">إجمالي الرفع</span>
</body></html>`);
for (const id of ['a','b','c','d']) {
  const w = await p.evaluate(i=>document.getElementById(i).getBoundingClientRect().width, id);
  console.log(id, w.toFixed(2));
}
await b.close();
